<script type="text/babel">
const { useState, useEffect, useRef } = React;
const API_BASE = ''; 
const Icon = ({ name, size = 20, className = "", fill = "none" }) => {
    const iconRef = useRef(null);
    useEffect(() => {
        if (window.lucide) {
            window.lucide.createIcons({
                root: iconRef.current ? iconRef.current.parentNode : document,
                nameAttr: 'data-lucide',
                attrs: { class: className, width: size, height: size, stroke: "currentColor", fill: fill }
            });
        }
    }, [name, className, size, fill]);
    return <i ref={iconRef} data-lucide={name} className={className}></i>;
};
const LoadingSpinner = () => ( <div className="flex justify-center items-center h-full"> <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-apple-blue"></div> </div> );

const AuthScreen = ({ onAuthSuccess }) => {
    const [isLogin, setIsLogin] = useState(true);
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [name, setName] = useState("");
    const [error, setError] = useState("");

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");
        try {
            if (isLogin) {
                const formData = new FormData();
                formData.append('username', email);
                formData.append('password', password);
                const res = await fetch(`${API_BASE}/token`, { method: 'POST', body: formData });
                if (!res.ok) throw new Error("Hibás email vagy jelszó");
                const data = await res.json();
                localStorage.setItem('token', data.access_token);
                onAuthSuccess();
            } else {
                const res = await fetch(`${API_BASE}/api/register`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ email, password, full_name: name })
                });
                if (!res.ok) throw new Error("A regisztráció sikertelen. Lehet, hogy az email már foglalt.");
                setIsLogin(true);
            }
        } catch (err) { setError(err.message); }
    };

    return (
        <div className="flex items-center justify-center h-screen bg-apple-bg p-6 animate-fade-in">
            <div className="w-full max-w-sm bg-apple-surface border border-apple-border rounded-2xl p-8 shadow-2xl">
                <div className="flex justify-center mb-6">
                    <div className="w-16 h-16 bg-apple-blue/20 rounded-2xl flex items-center justify-center">
                        <Icon name="terminal" size={32} className="text-apple-blue" />
                    </div>
                </div>
                <h1 className="text-2xl font-display font-bold text-center text-apple-text mb-2">{isLogin ? "Üdv újra!" : "Fiók létrehozása"}</h1>
                <p className="text-center text-apple-subtext text-sm mb-8">{isLogin ? "Jelentkezz be a folytatáshoz" : "Kezdd el a fejlesztést még ma"}</p>

                {error && <div className="mb-4 p-3 bg-red-500/10 border border-red-500/20 text-red-500 text-xs rounded-lg">{error}</div>}

                <form onSubmit={handleSubmit} className="space-y-4">
                    {!isLogin && (
                        <div className="space-y-1">
                            <label className="text-xs font-medium text-apple-subtext uppercase ml-1">Teljes név</label>
                            <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-apple-bg border border-apple-border rounded-xl p-3 text-apple-text outline-none focus:border-apple-blue transition-colors" required />
                        </div>
                    )}
                    <div className="space-y-1">
                        <label className="text-xs font-medium text-apple-subtext uppercase ml-1">Email</label>
                        <input type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-apple-bg border border-apple-border rounded-xl p-3 text-apple-text outline-none focus:border-apple-blue transition-colors" required />
                    </div>
                    <div className="space-y-1">
                        <label className="text-xs font-medium text-apple-subtext uppercase ml-1">Jelszó</label>
                        <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-apple-bg border border-apple-border rounded-xl p-3 text-apple-text outline-none focus:border-apple-blue transition-colors" required />
                    </div>
                    <button type="submit" className="w-full bg-apple-blue hover:bg-apple-blueActive text-white font-semibold py-3.5 rounded-xl transition-all active:scale-[0.98] shadow-lg shadow-apple-blue/20 mt-2">
                        {isLogin ? "Bejelentkezés" : "Regisztráció"}
                    </button>
                </form>
                <div className="mt-6 text-center">
                    <button onClick={() => setIsLogin(!isLogin)} className="text-sm text-apple-subtext hover:text-apple-text transition-colors">
                        {isLogin ? "Nincs még fiókod? Regisztrálj" : "Már van fiókod? Belépés"}
                    </button>
                </div>
            </div>
        </div>
    );
};

const Dashboard = ({ onOpenProject, user, onLogout }) => {
    const [searchQuery, setSearchQuery] = useState("");
    const [projects, setProjects] = useState([]);
    const [isCreating, setIsCreating] = useState(false);
    const [newProjectName, setNewProjectName] = useState("");
    const [newProjectLang, setNewProjectLang] = useState("Python");

    useEffect(() => {
        fetch(`${API_BASE}/api/projects`, { headers: { 'Authorization': `Bearer ${localStorage.getItem('token')}` } })
            .then(res => res.json())
            .then(data => setProjects(data.projects || []))
            .catch(console.error);
    }, []);

    const createProject = async () => {
        if(!newProjectName) return;
        try {
            const res = await fetch(`${API_BASE}/api/projects`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${localStorage.getItem('token')}` },
                body: JSON.stringify({ name: newProjectName, language: newProjectLang })
            });
            if(res.ok) {
                const project = await res.json();
                onOpenProject(project);
            }
        } catch(e) { console.error(e); }
    };

    const filteredProjects = projects.filter(p => p.name.toLowerCase().includes(searchQuery.toLowerCase()));

    return (
        <div className="flex flex-col h-screen bg-apple-bg overflow-y-auto safe-pt safe-pb">
            {isCreating && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in">
