                        <input type="text" placeholder="Projekt neve" value={newProjectName} onChange={e => setNewProjectName(e.target.value)} className="w-full bg-apple-bg border border-apple-border rounded-xl p-3 text-apple-text outline-none mb-3" />
                        <select value={newProjectLang} onChange={e => setNewProjectLang(e.target.value)} className="w-full bg-apple-bg border border-apple-border rounded-xl p-3 text-apple-text outline-none mb-6">
                            <option value="Python">Python</option>
                            <option value="Node.js">Node.js</option>
                            <option value="HTML">HTML/Static</option>
                        </select>
                        <div className="flex gap-2">
                            <button onClick={() => setIsCreating(false)} className="flex-1 bg-apple-surface2 text-apple-text py-3 rounded-xl font-medium">Mégse</button>
                            <button onClick={createProject} className="flex-1 bg-apple-blue text-white py-3 rounded-xl font-medium">Létrehozás</button>
                        </div>
                    </div>
                </div>
            )}
            <div className="px-6 py-6 pb-2">
                <div className="flex justify-between items-center mb-6">
                    <div className="w-10 h-10 rounded-full bg-apple-surface border border-apple-border flex items-center justify-center text-apple-text font-bold text-lg">
                        {user.full_name[0]}
                    </div>
                    <button onClick={onLogout} className="w-10 h-10 rounded-full bg-apple-surface border border-apple-border flex items-center justify-center text-apple-red">
                        <Icon name="log-out" size={18} />
                    </button>
                </div>
                <h1 className="text-3xl font-display font-bold text-apple-text mb-1">Szia, {user.full_name.split(' ')[0]}!</h1>
                <p className="text-apple-subtext text-sm">Kreditek: {user.credits.toFixed(1)} CR</p>
            </div>
            <div className="px-6 mb-6">
                <div className="relative">
                    <Icon name="search" size={18} className="absolute left-3 top-3 text-apple-subtext" />
                    <input type="text" placeholder="Keresés..." className="w-full bg-apple-surface text-apple-text py-3 pl-10 pr-4 rounded-xl outline-none border border-apple-border focus:border-apple-blue transition-colors" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
                </div>
            </div>
            <div className="px-6 mb-8">
                <div className="flex justify-between items-center mb-4">
                    <h2 className="text-lg font-semibold text-apple-text">Gyors indítás</h2>
                </div>
                <div className="flex gap-4 overflow-x-auto no-scrollbar pb-2">
                    <button onClick={() => { setIsCreating(true); setNewProjectLang("Python"); }} className="flex flex-col items-center gap-2 min-w-[80px]">
                        <div className="w-16 h-16 rounded-2xl bg-blue-500/20 flex items-center justify-center border border-blue-500/30">
                            <Icon name="code-2" className="text-blue-400" size={28} />
                        </div>
                        <span className="text-xs text-apple-subtext">Python</span>
                    </button>
                    <button onClick={() => { setIsCreating(true); setNewProjectLang("Node.js"); }} className="flex flex-col items-center gap-2 min-w-[80px]">
                        <div className="w-16 h-16 rounded-2xl bg-green-500/20 flex items-center justify-center border border-green-500/30">
                            <Icon name="server" className="text-green-500" size={28} />
                        </div>
                        <span className="text-xs text-apple-subtext">Node.js</span>
                    </button>
                    <button onClick={() => { setIsCreating(true); setNewProjectLang("HTML"); }} className="flex flex-col items-center gap-2 min-w-[80px]">
                        <div className="w-16 h-16 rounded-2xl bg-orange-500/20 flex items-center justify-center border border-orange-500/30">
                            <Icon name="globe" className="text-orange-500" size={28} />
                        </div>
                        <span className="text-xs text-apple-subtext">Web</span>
                    </button>
                    <button onClick={() => setIsCreating(true)} className="flex flex-col items-center gap-2 min-w-[80px]">
                        <div className="w-16 h-16 rounded-2xl bg-apple-surface border border-apple-border flex items-center justify-center">
                            <Icon name="plus" className="text-apple-text" size={28} />
                        </div>
                        <span className="text-xs text-apple-subtext">Egyéb</span>
                    </button>
                </div>
            </div>
            <div className="px-6 flex-1">
                <div className="flex justify-between items-center mb-4">
                    <h2 className="text-lg font-semibold text-apple-text">Saját projektek</h2>
                </div>
                <div className="flex flex-col gap-3 pb-24">
                    {filteredProjects.map(project => (
                        <button key={project.id} onClick={() => onOpenProject(project)} className="flex items-center p-4 bg-apple-surface rounded-2xl border border-apple-border active:scale-[0.98] transition-transform text-left">
