            </div>
            <div className="fixed bottom-0 left-0 right-0 h-20 bg-apple-bg/90 backdrop-blur-xl border-t border-apple-border flex justify-around items-center pb-safe">
                <button className="flex flex-col items-center gap-1 text-apple-blue"><Icon name="home" size={24} /><span className="text-[10px] font-medium">Főoldal</span></button>
                <button className="flex flex-col items-center gap-1 text-apple-subtext"><Icon name="search" size={24} /><span className="text-[10px] font-medium">Keresés</span></button>
                <button onClick={() => setIsCreating(true)} className="w-12 h-12 bg-apple-blue rounded-full flex items-center justify-center text-white shadow-lg -mt-6 border-4 border-apple-bg"><Icon name="plus" size={24} /></button>
