@app.route('/api/ai/chat', methods=['POST'])
@token_required
def ai_chat(current_user):
    data = request.json
    message = data.get('message', '')
    project_id = data.get('project_id')
    if not message:
        return jsonify({'error': 'Message required'}), 400
    conn = get_db()
    c = conn.cursor()
    if current_user['credits'] < 1.0:
        conn.close()
        return jsonify({'error': 'Insufficient credits'}), 402
    grok_response = ''
    try:
        grok_payload = {
            'model': 'grok-2-1212',
            'messages': [
                {'role': 'system', 'content': 'You are a fast reasoning AI for planning code tasks.'},
                {'role': 'user', 'content': message}
            ],
            'max_tokens': 2048,
            'temperature': 0.7
        }
        grok_headers = {
            'Authorization': f'Bearer {XAI_API_KEY}',
            'Content-Type': 'application/json'
        }
        grok_req = requests.post(XAI_API_URL, headers=grok_headers, json=grok_payload, timeout=30)
        if grok_req.status_code == 200:
            grok_data = grok_req.json()
            grok_response = grok_data.get('choices', [{}])[0].get('message', {}).get('content', '')
    except Exception as e:
        grok_response = message
    claude_response = ''
    try:
        bedrock = boto3.client(
            'bedrock-runtime',
            region_name=AWS_REGION,
            aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
            aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY')
        )
        claude_prompt = f"Based on this reasoning: {grok_response}\n\nUser request: {message}\n\nProvide a helpful response or code snippet."
        claude_payload = {
            'anthropic_version': 'bedrock-2023-05-31',
            'max_tokens': 4096,
            'temperature': 0.7,
            'messages': [
                {'role': 'user', 'content': [{'type': 'text', 'text': claude_prompt}]}
            ]
        }
        claude_req = bedrock.invoke_model(
            modelId='anthropic.claude-3-5-sonnet-20241022-v2:0',
            body=json.dumps(claude_payload)
        )
        claude_data = json.loads(claude_req['body'].read())
        claude_response = claude_data.get('content', [{}])[0].get('text', 'Sorry, I could not process your request.')
    except Exception as e:
        claude_response = f"AI assistant: {grok_response if grok_response else 'I understand your request and will help you.'}"
    if project_id:
        c.execute('SELECT history_json FROM ai_conversations WHERE project_id = ?', (project_id,))
        conv = c.fetchone()
        if conv:
            history = json.loads(conv['history_json'] or '[]')
            history.append({'role': 'user', 'content': message})
            history.append({'role': 'assistant', 'content': claude_response})
            c.execute('UPDATE ai_conversations SET history_json = ? WHERE project_id = ?',
                      (json.dumps(history), project_id))
    credits_used = 0.5
    c.execute('UPDATE users SET credits = credits - ? WHERE id = ?', (credits_used, current_user['id']))
    c.execute('SELECT usage_json FROM billing WHERE user_id = ?', (current_user['id'],))
    billing = c.fetchone()
    if billing:
        usage = json.loads(billing['usage_json'] or '{}')
        usage[datetime.now().strftime('%Y-%m')] = usage.get(datetime.now().strftime('%Y-%m'), 0) + credits_used
        c.execute('UPDATE billing SET usage_json = ? WHERE user_id = ?',
                  (json.dumps(usage), current_user['id']))
    conn.commit()
    conn.close()
    return jsonify({'response': claude_response})

