};

const IDE = ({ project, onBack }) => {
    const [activeTab, setActiveTab] = useState('agent');
    const [activeFile, setActiveFile] = useState(null);
    const [files, setFiles] = useState([]);
    const [fileContent, setFileContent] = useState('');
    const [terminalOutput, setTerminalOutput] = useState([]);
    const [isSidebarOpen, setSidebarOpen] = useState(false);
    const [isToolsOpen, setToolsOpen] = useState(false);
    const [agentMessages, setAgentMessages] = useState([]);
    const [ws, setWs] = useState(null);
    const [agentInput, setAgentInput] = useState('');

    useEffect(() => {
        loadFiles();
        const socket = io(API_BASE);
        socket.on('connect', () => {
            socket.emit('join_project', { project_id: project.id });
        });
        socket.on('file_update', (data) => {
            if (data.project_id === project.id) {
                loadFiles();
            }
        });
        setWs(socket);
        return () => socket.close();
    }, []);

    const loadFiles = async () => {
        const res = await fetch(`${API_BASE}/api/projects/${project.id}/files`, { headers: { 'Authorization': `Bearer ${localStorage.getItem('token')}` } });
        const data = await res.json();
        setFiles(data.files || []);
        if(!activeFile && data.files && data.files.length > 0) loadFile(data.files[0].name, false);
    };

    const loadFile = async (filename, switchTab = true) => {
        const res = await fetch(`${API_BASE}/api/projects/${project.id}/file?name=${filename}`, { headers: { 'Authorization': `Bearer ${localStorage.getItem('token')}` } });
        const data = await res.json();
        setActiveFile(filename);
        setFileContent(data.content || '');
        if (switchTab) { setActiveTab('editor'); setSidebarOpen(false); }
    };

    const saveFile = async (content) => {
        setFileContent(content);
        if(!activeFile) return;
        await fetch(`${API_BASE}/api/projects/${project.id}/file?name=${activeFile}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${localStorage.getItem('token')}` },
            body: JSON.stringify({ content })
        });
    };

    const handleRun = async () => {
        if(!activeFile) return;
        setTerminalOutput(prev => [...prev, `> ${activeFile} futtatása...`]);
        setActiveTab('console');
        const res = await fetch(`${API_BASE}/api/terminal/exec`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${localStorage.getItem('token')}` },
            body: JSON.stringify({ command: `run ${activeFile}` })
        });
        const data = await res.json();
        setTerminalOutput(prev => [...prev, data.output || '']);
    };

    const handleAgentChat = async (message) => {
        if(!message.trim()) return;
        const newMessage = { role: 'user', content: message };
        setAgentMessages(prev => [...prev, newMessage]);
        setAgentInput('');
        const res = await fetch(`${API_BASE}/api/ai/chat`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${localStorage.getItem('token')}` },
            body: JSON.stringify({ message, project_id: project.id })
        });
        const data = await res.json();
        setAgentMessages(prev => [...prev, { role: 'assistant', content: data.response || 'Hiba történt' }]);
        loadFiles();
    };

    const ToolItem = ({ icon, title, desc, color, onClick }) => (
        <div onClick={onClick} className="flex gap-4 p-3 rounded-xl active:bg-apple-surface transition-colors cursor-pointer bg-apple-surface border border-apple-border/50">
            <Icon name={icon} size={24} className={`${color} shrink-0 mt-1`} />
            <div className="flex flex-col">
                <span className="text-apple-text font-display font-medium text-base">{title}</span>
                <span className="text-apple-subtext text-sm leading-snug mt-1">{desc}</span>
            </div>
        </div>
    );

    return (
        <div className="flex flex-col h-screen w-full bg-apple-bg relative animate-fade-in">
            <div className="h-14 bg-apple-bg/90 backdrop-blur-md flex items-center justify-between px-4 border-b border-apple-border z-20 safe-pt fixed top-0 w-full">
                <button className="text-apple-blue" onClick={() => setSidebarOpen(true)}><Icon name="menu" size={24} /></button>
                <div className="flex flex-col items-center">
                    <span className="text-apple-text font-display font-semibold text-sm">{project.name}</span>
                    <span className="text-apple-subtext text-[10px]">{activeFile || 'Nincs fájl kiválasztva'}</span>
                </div>
                <button className="text-apple-blue" onClick={() => setToolsOpen(true)}><Icon name="more-horizontal" size={24} /></button>
            </div>
            <main className="flex-1 flex flex-col overflow-hidden relative">
                {activeTab === 'editor' && (
                    <div className="flex flex-1 overflow-hidden bg-apple-bg relative pt-14 pb-16">
                        <div className="w-10 bg-apple-bg flex flex-col items-end pr-2 pt-4 select-none border-r border-apple-border z-10">
                            {fileContent.split('\n').map((_, i) => <div key={i} className="text-xs text-apple-subtext font-mono leading-6">{i + 1}</div>)}
                        </div>
                        <textarea className="flex-1 bg-transparent text-apple-text font-mono text-sm leading-6 p-4 outline-none resize-none whitespace-pre" value={fileContent} onChange={(e) => saveFile(e.target.value)} spellCheck="false" />
                    </div>
                )}
                {activeTab === 'preview' && (
                    <div className="flex flex-1 flex-col items-center justify-center bg-apple-bg text-center p-8 pt-14 pb-16">
                        <Icon name="monitor" size={48} className="text-apple-subtext mb-4" />
                        <h3 className="text-apple-text font-display font-medium text-lg mb-2">Előnézet</h3>
                        <p className="text-apple-subtext text-sm max-w-xs">Az alkalmazás fut a szerveren.</p>
                    </div>
                )}
                {activeTab === 'agent' && (
                    <div className="flex flex-1 flex-col bg-apple-bg pt-14 pb-16">
                        <div className="flex-1 overflow-y-auto p-4 space-y-4">
                            {agentMessages.length === 0 ? (
                                <div className="flex flex-col items-center justify-center h-full mt-20">
                                    <div className="w-16 h-16 bg-apple-surface rounded-2xl flex items-center justify-center mb-4 shadow-lg border border-apple-border"><Icon name="sparkles" className="text-apple-blue" size={32} /></div>
                                    <h2 className="text-xl font-display font-semibold text-apple-text mb-2">Szia! Miben segíthetek?</h2>
                                    <p className="text-apple-subtext text-center text-sm px-8 mb-8">Írd le mit szeretnél, és én megírom a kódot.</p>
                                    <div className="grid grid-cols-2 gap-2 w-full px-4">
                                        <button onClick={() => { setAgentInput('Javítsd ki a hibákat'); }} className="bg-apple-surface text-xs text-apple-text p-3 rounded-lg border border-apple-border text-left">Hibakeresés</button>
                                        <button onClick={() => { setAgentInput('Adj hozzá új funkciót'); }} className="bg-apple-surface text-xs text-apple-text p-3 rounded-lg border border-apple-border text-left">Új funkció</button>
                                    </div>
                                </div>
                            ) : (
                                agentMessages.map((msg, i) => (
                                    <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                        <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-apple-blue text-white' : 'bg-apple-surface text-apple-text'}`}>{msg.content}</div>
                                    </div>
                                ))
                            )}
                        </div>
                        <div className="p-4 border-t border-apple-border bg-apple-bg safe-pb">
                            <div className="bg-apple-surface rounded-pill flex items-center px-4 py-3 border border-apple-border">
                                <input type="text" placeholder="Ide írj..." value={agentInput} onChange={(e) => setAgentInput(e.target.value)} className="bg-transparent flex-1 text-apple-text outline-none text-sm placeholder-apple-subtext" onKeyDown={(e) => { if (e.key === 'Enter') { handleAgentChat(agentInput); } }} />
                                <button className="text-apple-blue" onClick={() => handleAgentChat(agentInput)}><Icon name="arrow-up-circle" size={24} /></button>
                            </div>
                        </div>
                    </div>
                )}
                {activeTab === 'console' && (
                    <div className="flex flex-1 flex-col bg-apple-bg p-4 font-mono text-sm overflow-y-auto pt-14 pb-16">
                        {terminalOutput.map((line, i) => <div key={i} className="text-apple-text mb-1 border-b border-apple-border pb-1 whitespace-pre-wrap">{line}</div>)}
                        <div className="flex items-center text-apple-subtext mt-2"><span className="mr-2">➜</span><div className="w-2 h-4 bg-apple-blue animate-pulse"></div></div>
                    </div>
                )}
            </main>
            <div className="fixed bottom-0 left-0 right-0 h-16 bg-apple-bg/90 backdrop-blur-md border-t border-apple-border flex items-center px-4 justify-between z-30 safe-pb">
                <button onClick={handleRun} className="w-10 h-10 bg-apple-blue rounded-full flex items-center justify-center text-white shadow-lg active:scale-95 transition-transform"><Icon name="play" size={18} fill="currentColor" /></button>
                <div className="h-10 bg-apple-surface rounded-full flex items-center p-1 border border-apple-border">
                    <button onClick={() => setActiveTab('preview')} className={`h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'preview' ? 'bg-apple-border text-white' : 'text-apple-subtext'}`}><Icon name="monitor" size={18} /></button>
                    <button onClick={() => setActiveTab('agent')} className={`h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'agent' ? 'bg-apple-border text-apple-blue' : 'text-apple-subtext'}`}><Icon name="sparkles" size={18} /></button>
                    <button onClick={() => setActiveTab('console')} className={`h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'console' ? 'bg-apple-border text-white' : 'text-apple-subtext'}`}><Icon name="terminal-square" size={18} /></button>
                </div>
                <button onClick={() => setToolsOpen(true)} className="w-10 h-10 flex items-center justify-center text-apple-blue"><Icon name="layout-grid" size={22} /></button>
            </div>
            <div className={`fixed inset-0 z-50 transform transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
                <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setSidebarOpen(false)}></div>
                <div className="absolute top-0 bottom-0 left-0 w-3/4 max-w-xs bg-apple-surface border-r border-apple-border flex flex-col animate-slide-right">
                    <div className="h-14 flex items-center px-4 border-b border-apple-border justify-between safe-pt bg-apple-bg/50 backdrop-blur-xl">
                        <span className="font-display font-semibold text-apple-text text-lg">Fájlok</span>
                        <button onClick={() => setSidebarOpen(false)} className="text-apple-blue"><Icon name="x" size={20} /></button>
                    </div>
                    <div className="p-4"><button onClick={onBack} className="w-full py-2 bg-apple-surface2 rounded-lg text-sm text-apple-red font-medium flex items-center justify-center gap-2 mb-4"><Icon name="log-out" size={16} /> Kilépés a Főoldalra</button></div>
                    <div className="flex-1 overflow-y-auto p-2">
                        {files.map((file, i) => (
                            <button key={i} onClick={() => loadFile(file.name)} className={`w-full flex items-center p-3 rounded-lg mb-1 text-sm transition-colors ${activeFile === file.name ? 'bg-apple-blue text-white' : 'text-apple-subtext hover:text-apple-text hover:bg-white/5'}`}>
                                <Icon name={file.name.endsWith('.py') ? 'file-code' : 'file'} size={18} className="mr-3" /><span className="font-medium">{file.name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
            <div className={`fixed inset-0 z-50 flex items-end justify-center transition-opacity duration-200 ${isToolsOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
                <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setToolsOpen(false)}></div>
                <div className={`relative bg-apple-surface border-t border-apple-border rounded-t-3xl w-full max-w-2xl p-6 safe-pb transition-transform duration-300 ${isToolsOpen ? 'translate-y-0' : 'translate-y-full'}`}>
                    <div className="w-12 h-1 bg-apple-border rounded-full mx-auto mb-6"></div>
                    <h2 className="text-xl font-display font-bold text-apple-text mb-6">Eszközök</h2>
                    <div className="grid grid-cols-1 gap-3">
                        <ToolItem icon="file-plus" title="Új fájl" desc="Új fájl hozzáadása a projekthez" color="text-apple-blue" onClick={() => setToolsOpen(false)} />
                        <ToolItem icon="upload" title="Importálás" desc="Fájlok feltöltése" color="text-apple-green" onClick={() => setToolsOpen(false)} />
                        <ToolItem icon="rocket" title="Publikálás" desc="Alkalmazás közzététele" color="text-apple-orange" onClick={() => setToolsOpen(false)} />
                        <ToolItem icon="settings" title="Beállítások" desc="Projekt beállítások" color="text-apple-subtext" onClick={() => setToolsOpen(false)} />
                    </div>
                </div>
            </div>
        </div>
    );
};

const App = () => {
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [user, setUser] = useState(null);
    const [currentProject, setCurrentProject] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const token = localStorage.getItem('token');
        if (token) {
            fetch(`${API_BASE}/api/me`, { headers: { 'Authorization': `Bearer ${token}` } })
                .then(res => res.json())
                .then(data => {
                    if (data.id) {
                        setUser(data);
                        setIsAuthenticated(true);
                    }
                    setLoading(false);
                })
                .catch(() => {
                    localStorage.removeItem('token');
                    setLoading(false);
                });
        } else {
            setLoading(false);
        }
    }, []);

    const handleAuthSuccess = () => {
        const token = localStorage.getItem('token');
        if (token) {
            fetch(`${API_BASE}/api/me`, { headers: { 'Authorization': `Bearer ${token}` } })
                .then(res => res.json())
                .then(data => {
                    setUser(data);
                    setIsAuthenticated(true);
                });
        }
    };

    const handleLogout = () => {
        localStorage.removeItem('token');
        setIsAuthenticated(false);
        setUser(null);
        setCurrentProject(null);
    };

    const handleOpenProject = (project) => {
        setCurrentProject(project);
    };

    const handleBackToDashboard = () => {
        setCurrentProject(null);
    };

    if (loading) {
        return <LoadingSpinner />;
    }

    if (!isAuthenticated) {
        return <AuthScreen onAuthSuccess={handleAuthSuccess} />;
    }

    if (currentProject) {
        return <IDE project={currentProject} onBack={handleBackToDashboard} />;
    }

    return <Dashboard onOpenProject={handleOpenProject} user={user} onLogout={handleLogout} />;
};

ReactDOM.render(<App />, document.getElementById('root'));
</script>
</body>
</html>
